1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const countSphinxes = (army: Card[]): number =>
9	  army.filter((card) => card.monster === SPHINX).length;
10	
11	const RANKLESS = "no-rank";
12	
13	const typeKeyOf = (card: Card): string =>
14	  `${card.monster}:${card.rank ?? RANKLESS}`;
15	
16	const countDistinctTypes = (army: Card[]): number =>
17	  new Set(army.map(typeKeyOf)).size;
18	
19	const TYPE_BONUS_THRESHOLD = 3;
20	const POINTS_PER_TYPE = 1;
21	const POINTS_PER_TYPE_WITH_BONUS = 2;
22	
23	const pointsPerType = (typeCount: number): number =>
24	  typeCount > TYPE_BONUS_THRESHOLD ? POINTS_PER_TYPE_WITH_BONUS : POINTS_PER_TYPE;
25	
26	export const scoreArmy = (army: Card[]): number => {
27	  const typeCount = countDistinctTypes(army);
28	  return countSphinxes(army) * typeCount * pointsPerType(typeCount);
29	};
