1	import { describe, it, expect } from "vitest";
2	import { scoreArmy } from "./sphinx-score.js";
3	
4	describe("Sphinx scoring", () => {
5	  // No Sphinx in the army — only Sphinx cards produce points
6	  it("scores an empty army as 0", () => {
7	    expect(scoreArmy([])).toBe(0);
8	  });
9	  it("scores an army with no Sphinx as 0 — [hydra, zombie] is 0", () => {
10	    expect(scoreArmy([{ monster: "hydra" }, { monster: "zombie" }])).toBe(0);
11	  });
12	
13	  // Single Sphinx, type count at or below three → 1 point per type
14	  it("scores a lone Sphinx as 1 — 1 type, not beyond three, 1 per type", () => {
15	    expect(scoreArmy([{ monster: "sphinx" }])).toBe(1);
16	  });
17	  it("scores [sphinx, hydra] as 2 — 2 types at 1 per type", () => {
18	    expect(scoreArmy([{ monster: "sphinx" }, { monster: "hydra" }])).toBe(2);
19	  });
20	  it("scores [sphinx, hydra, zombie] as 3 — 3 types at 1 per type", () => {
21	    expect(
22	      scoreArmy([{ monster: "sphinx" }, { monster: "hydra" }, { monster: "zombie" }]),
23	    ).toBe(3);
24	  });
25	
26	  // Single Sphinx, type count beyond three → 2 points per type
27	  it("scores [sphinx, hydra, zombie, cyclops] as 8 — 4 types at 2 per type", () => {
28	    expect(
29	      scoreArmy([
30	        { monster: "sphinx" },
31	        { monster: "hydra" },
32	        { monster: "zombie" },
33	        { monster: "cyclops" },
34	      ]),
35	    ).toBe(8);
36	  });
37	  it("scores [sphinx, hydra, zombie, cyclops, orthrus] as 10 — 5 types at 2 per type", () => {
38	    expect(
39	      scoreArmy([
40	        { monster: "sphinx" },
41	        { monster: "hydra" },
42	        { monster: "zombie" },
43	        { monster: "cyclops" },
44	        { monster: "orthrus" },
45	      ]),
46	    ).toBe(10);
47	  });
48	
49	  // Duplicate cards collapse to a single type
50	  it("counts repeated monsters once — [sphinx, hydra, hydra] is 2", () => {
51	    expect(
52	      scoreArmy([{ monster: "sphinx" }, { monster: "hydra" }, { monster: "hydra" }]),
53	    ).toBe(2);
54	  });
55	
56	  // Undead Warrior ranks are distinct types
57	  it("counts one Undead Warrior rank as one type — [sphinx, undead-warrior(2), hydra] is 3", () => {
58	    expect(
59	      scoreArmy([
60	        { monster: "sphinx" },
61	        { monster: "undead-warrior", rank: 2 },
62	        { monster: "hydra" },
63	      ]),
64	    ).toBe(3);
65	  });
66	  it("counts two Undead Warrior ranks as two types — [sphinx, undead-warrior(1), undead-warrior(2)] is 3", () => {
67	    expect(
68	      scoreArmy([
69	        { monster: "sphinx" },
70	        { monster: "undead-warrior", rank: 1 },
71	        { monster: "undead-warrior", rank: 2 },
72	      ]),
73	    ).toBe(3);
74	  });
75	  it("counts three Undead Warrior ranks as three types — [sphinx, undead-warrior(1), undead-warrior(2), undead-warrior(3)] is 8", () => {
76	    expect(
77	      scoreArmy([
78	        { monster: "sphinx" },
79	        { monster: "undead-warrior", rank: 1 },
80	        { monster: "undead-warrior", rank: 2 },
81	        { monster: "undead-warrior", rank: 3 },
82	      ]),
83	    ).toBe(8);
84	  });
85	  it("counts repeated Undead Warriors of the same rank once — [sphinx, undead-warrior(2), undead-warrior(2)] is 2", () => {
86	    expect(
87	      scoreArmy([
88	        { monster: "sphinx" },
89	        { monster: "undead-warrior", rank: 2 },
90	        { monster: "undead-warrior", rank: 2 },
91	      ]),
92	    ).toBe(2);
93	  });
94	
95	  // Multiple Sphinx cards each score
96	  it("scores each Sphinx card — [sphinx, sphinx] is 2", () => {
97	    expect(scoreArmy([{ monster: "sphinx" }, { monster: "sphinx" }])).toBe(2);
98	  });
99	  it("scores each Sphinx card beyond three types — [sphinx, sphinx, hydra, zombie, cyclops] is 16", () => {
100	    expect(
101	      scoreArmy([
